-- NFL run concept shares by season and yards by concept
rsql with r as (select lp.season s, json_extract(j.value,'$.call') c, json_extract(j.value,'$.yards') y, json_extract(j.value,'$.before_contact') ybc from log_plays lp, json_each(more('log_plays', lp._more), '$.plays') j where lp.stream = 'nfl' and json_extract(j.value,'$.kind') = 'Run'), k as (select s, y, ybc, case when c like '%outside zone%' then 'outside zone' when c like '%inside zone%' then 'inside zone' when c like '%zone read%' then 'zone read' when c like '%QB%' then 'QB design' when c like '%jet sweep%' or c like '%sweep%' then 'sweep' when c like '%toss%' then 'toss' when c like '%counter%' then 'counter' when c like '%power%' then 'power' when c like '%draw%' then 'draw' when c like '%duo%' then 'duo' when c like '%trap%' then 'trap' when c like '%dive%' then 'dive' else 'other' end fam from r) select fam, case when s <= 2028 then 'early' when s >= 2032 then 'late' else 'mid' end per, count(*) n, round(avg(y),3) yards, round(avg(ybc),3) ybc from k where s >= 2026 group by fam, per order by fam, per
-- share by family each season
rsql with r as (select lp.season s, json_extract(j.value,'$.call') c from log_plays lp, json_each(more('log_plays', lp._more), '$.plays') j where lp.stream = 'nfl' and json_extract(j.value,'$.kind') = 'Run'), k as (select s, case when c like '%outside zone%' then 'outside zone' when c like '%inside zone%' then 'inside zone' when c like '%zone read%' then 'zone read' when c like '%QB%' then 'QB design' when c like '%jet sweep%' or c like '%sweep%' then 'sweep' when c like '%toss%' then 'toss' when c like '%counter%' then 'counter' when c like '%power%' then 'power' when c like '%draw%' then 'draw' when c like '%duo%' then 'duo' when c like '%trap%' then 'trap' when c like '%dive%' then 'dive' else 'other' end fam from r) select s, round(avg(fam='outside zone'),4) oz, round(avg(fam='inside zone'),4) iz, round(avg(fam='zone read'),4) zr, round(avg(fam='QB design'),4) qb, round(avg(fam='sweep'),4) sweep, round(avg(fam='toss'),4) toss, round(avg(fam='counter'),4) counter, round(avg(fam='power'),4) power, round(avg(fam='draw'),4) draw, round(avg(fam='duo'),4) duo, round(avg(fam='other'),4) other from k where s >= 2026 group by s order by s
-- direction and audible shares
rsql with r as (select lp.season s, json_extract(j.value,'$.call') c, json_extract(j.value,'$.yards') y from log_plays lp, json_each(more('log_plays', lp._more), '$.plays') j where lp.stream = 'nfl' and json_extract(j.value,'$.kind') = 'Run') select s, round(avg(c like '%(audible)%'),4) audible, round(avg(c like '%motion%' or c like '%shift%'),4) motion, round(avg(c like 'gun%' or c like '%gun %'),4) gun, round(avg(c like '%left%'),4) left_share, round(avg(c like '%RPO%'),4) rpo from r where s >= 2026 group by s order by s
-- the first words of run calls (formation) share by season
rsql select substr(json_extract(j.value,'$.call'),1,8) f, count(*) n from log_plays lp, json_each(more('log_plays', lp._more), '$.plays') j where lp.stream = 'nfl' and lp.season = 2034 and json_extract(j.value,'$.kind') = 'Run' group by f order by n desc limit 12
